using System.Runtime.InteropServices;

namespace Legio.Protocol;

/// <summary>
/// Tessera (The Tablet/Tile).
/// Compact, blittable performance report generated by Centurions after processing a cohort phase.
/// </summary>
[StructLayout(LayoutKind.Sequential)]
public struct Tessera
{
    /// <summary>
    /// Total duration of the reported work in Stopwatch ticks.
    /// </summary>
    public long DurationTicks;

    /// <summary>
    /// Number of items actually processed by this Centurion during this report.
    /// </summary>
    public int ItemCount;

    /// <summary>
    /// Total items scheduled for this Cohort in the frame (gives Oracle true workload scale).
    /// </summary>
    public int TotalCohortItems;

    /// <summary>
    /// ID of the Centurion (Thread) that performed the work.
    /// </summary>
    public int CenturioId;

    /// <summary>
    /// ID of the Cohort (System) reporting.
    /// </summary>
    public int CohortId;

    /// <summary>
    /// Number of successful work steals performed by this Centurion during this phase.
    /// </summary>
    public int StealCount;

    /// <summary>
    /// Number of CAS contentions experienced while stealing during this phase.
    /// </summary>
    public int ContentionCount;

    /// <summary>
    /// Current normalized CPU pressure [0.0 - 1.0] observed by Speculator.
    /// </summary>
    public float CpuPressure;

    private int _padding;
}